import numpy as np, json
D='/work/fwd_3'
meta=json.load(open(D+'/meta.json'))
ids=[np.array(r) for r in meta['token_ids']]
topids=np.load(D+'/topk_ids.npy')  # [t, pos, k]
toplog=np.load(D+'/topk_logprobs.npy')
lengths=meta['lengths']
Wait=13784
def tok(i):
    return repr(tok.id_to_token(int(i)))
print('=== loop positions (text 1) ===')
shown=0
for p in range(1,lengths[1]-1):
    if ids[1][p+1]==Wait and shown<12:
        print(f'pos {p}: tok_t={tok(ids[1][p])} next=Wait | top5 next: ' + ', '.join(f'{tok(topids[1,p,i])} {toplog[1,p,i]:.2f}' for i in range(5)))
        shown+=1
print('=== finished text positions (text 2), sample ===')
for p in [100, 300, 500, 700, 900, 1050]:
    if p<lengths[2]-1:
        print(f'pos {p}: tok_t={tok(ids[2][p])} | top5: ' + ', '.join(f'{tok(topids[2,p,i])} {toplog[2,p,i]:.2f}' for i in range(5)))

